import json
from itertools import permutations

names = ["Kammer", "Lugo", "Trillo", "Waite", "Yoshida", "Zinn"]
rec = {"Kammer", "Lugo"}

def valid(order):
    pos = {n: i + 1 for i, n in enumerate(order)}
    if order[3] in rec:
        return False
    if order[4] not in rec:
        return False
