        return False
    if not pos["Zinn"] < pos["Yoshida"]:
        return False
    return True

sols = []
for p in permutations(names):
    if valid(p):
        pos = {n: i + 1 for i, n in enumerate(p)}
        if pos["Kammer"] + 1 == pos["Yoshida"]:
            sols.append(pos)

checks = {
    "A": lambda s: s["Kammer"] == 2,
    "B": lambda s: s["Trillo"] == 4,
    "C": lambda s: s["Waite"] == 3,
    "D": lambda s: s["Yoshida"] == 6,
    "E": lambda s: s["Zinn"] == 2,
}

possible = [k for k, f in checks.items() if any(f(s) for s in sols)]

if len(possible) == 1:
    print(json.dumps({
        "final_answer": possible[0],
        "evidence": {"num_solutions": len(sols), "possible": possible}
    }))
else:
    print("UNSUPPORTED")
